from typing import Literal

from pydantic import BaseModel, Field

# Thread ids are generated by the API (UUIDs). Only allow safe characters.
THREAD_ID_PATTERN = r"^[A-Za-z0-9-]{1,64}$"


class ChatRequest(BaseModel):
    message: str = Field(min_length=1, max_length=2000, examples=["Any 2 BHK in Hinjewadi under 28k?"])
    thread_id: str | None = Field(
        default=None,
        pattern=THREAD_ID_PATTERN,
        description="Leave empty to start a new conversation; send the returned id to continue it.",
    )


class ChatResponse(BaseModel):
    thread_id: str
    reply: str
    tools_used: list[str]
    guardrail: str | None = Field(
        default=None, description='Set when a guardrail acted: "handoff", "fair_housing" or "prompt_injection"'
    )


class HistoryMessage(BaseModel):
    role: Literal["user", "assistant"]
    content: str


class HistoryResponse(BaseModel):
    thread_id: str
    messages: list[HistoryMessage]